using System;
using System.Linq;
using System.Collections.Generic;
using EnusDE.Signaltechnik;

public static class ApproachReleaseTests {
    static void Check(bool ok,string message){if(!ok)throw new Exception("FAIL: "+message);System.Console.WriteLine("PASS: "+message);}
    sealed class World:IInterlockingWorld,IApproachStopWorld {
        public bool Approach,Moving=true,Unknown,Occupied,Known=true,Valid=true;
        public string Identity="train1";
        public bool PathValid(RouteDefinition r)=>Valid;
        public TrackOccupancy Occupancy(TrackSection s)=>Unknown?TrackOccupancy.Unknown:s.Segment=="approach"?Approach?TrackOccupancy.Occupied:TrackOccupancy.Clear:Occupied?TrackOccupancy.Occupied:TrackOccupancy.Clear;
        public bool SwitchPosition(string id,out bool value){value=false;return true;}
        public bool SetSwitch(string id,bool value)=>true;
        public bool StoppedApproach(RouteDefinition r,out string id,out string detail){id=Known?Identity:null;detail=Moving?"moving":"complete stopped train";return Known&&!Moving;}
    }
    static RouteDefinition Route(bool shunt=false)=>new RouteDefinition{Code=shunt?"R1":"F1",Entry="A",Exit="B",Shunting=shunt,Sections=new List<TrackSection>{new TrackSection{Segment="track",From=0,To=100}},Approach=new List<TrackSection>{new TrackSection{Segment="approach",From=0,To=300}},Switches=new List<RouteSwitch>()};
    static void Ready(InterlockingEngine e,RouteDefinition r,World w){e.Request(r,w);for(int i=0;i<8;i++)e.Tick(w);if(!e.ForSignal(r.Entry).Permitted)throw new Exception("fixture did not establish route");}
    public static void Run() {
        double now=0;var w=new World();var e=new InterlockingEngine(()=>now);var route=Route();Ready(e,route,w);w.Approach=true;e.RequestRelease(route.Id,"all",15);now=14;e.Tick(w);Check(e.Active.Count==1&&!e.ForSignal("A").Permitted,"auxiliary release first withdraws authority and retains locks throughout the minimum protection wait");now=15;e.Tick(w);Check(e.Active.Count==1,"expiry alone cannot release a route with a moving approach train");w.Moving=false;now=16;e.Tick(w);e.Tick(w);Check(e.Active.Count==1&&e.Active.Single().ApproachStopChecks==1,"duplicate reads of one instant do not count as multiple stationary confirmations");now=16.5;e.Tick(w);Check(e.Active.Count==1,"two stationary observations still retain the approach lock");now=17;e.Tick(w);Check(e.Active.Count==0,"free route can release after the wait and three distinct complete stopped-approach confirmations");
        now=0;w=new World();e=new InterlockingEngine(()=>now);route=Route();Ready(e,route,w);w.Approach=true;w.Moving=false;e.RequestRelease(route.Id,"all",0);now=1;e.Tick(w);now=1.5;e.Tick(w);w.Moving=true;now=2;e.Tick(w);w.Moving=false;now=2.5;e.Tick(w);Check(e.Active.Count==1&&e.Active.Single().ApproachStopChecks==1,"resumed approach movement resets stationary proof rather than retaining old confirmations");w.Identity="different-train";now=3;e.Tick(w);Check(e.Active.Single().ApproachStopChecks==1,"changed consist identity restarts stationary proof");w.Known=false;now=3.5;e.Tick(w);Check(e.Active.Single().ApproachStopChecks==0,"unknown consist or missing tail cannot grant auxiliary release");w.Known=true;w.Unknown=true;now=4;e.Tick(w);Check(e.Active.Count==1&&e.Active.Single().ApproachStopChecks==0,"unknown route or approach occupancy preserves the lock despite reported stillness");w.Unknown=false;w.Occupied=true;now=5;e.Tick(w);Check(e.Active.Count==1&&e.Active.Single().ApproachStopChecks==0,"occupied protected track cannot be released by stationary approach proof");w.Occupied=false;w.Valid=false;now=6;e.Tick(w);Check(e.Active.Count==1,"unreadable route topology remains locked during auxiliary release");
        now=0;w=new World();e=new InterlockingEngine(()=>now);var shunt=Route(true);Ready(e,shunt,w);w.Approach=true;try{e.Cancel(shunt.Id,w);}catch(InvalidOperationException){}route=Route();e.Request(route,w,15);Check(e.Active.Any(r=>r.Route.Id==route.Id&&r.Stage==RouteStage.WaitingProtection)&&e.Active.All(r=>!r.Permitted),"main route can take over a cancelled shunt consent while all affected signals remain at stop");now=15;e.Tick(w);Check(e.Active.Count==2&&!e.ForSignal("A").Permitted,"main-route priority never clears a moving approach train or ignores the old shunt locks");w.Moving=false;for(int i=0;i<8;i++){now=16+i*.5;e.Tick(w);}Check(e.Active.Count==1&&e.Active.Single().Route.Id==route.Id&&e.Active.Single().Permitted,"after stopped-approach proof the shunt lock is removed and the main route performs normal final checks before clearing");
        now=0;w=new World();e=new InterlockingEngine(()=>now);shunt=Route(true);Ready(e,shunt,w);e.HaltAll();route=Route();e.Request(route,w,15);Check(e.Active.Any(r=>r.Route.Id==route.Id&&r.Stage==RouteStage.WaitingProtection)&&e.Active.All(r=>!r.Permitted),"faulted shunt consent can enter controlled main-route withdrawal without forcing any signal to clear");
        now=0;w=new World();e=new InterlockingEngine(()=>now);route=Route();Ready(e,route,w);w.Unknown=true;w.Occupied=true;e.RequestRelease(route.Id,"all",15);e.ConfirmOperatorRelease(route.Id);now=14;e.Tick(w);Check(e.Active.Count==1&&!e.ForSignal("A").Permitted,"explicit dispatcher-confirmed auxiliary release still holds signals at stop until the protection wait expires");now=15;e.Tick(w);Check(e.Active.Count==0&&w.Unknown&&w.Occupied,"dispatcher confirmation releases only own locks despite an incorrect/unknown reading and never rewrites physical occupancy");
        now=0;w=new World();e=new InterlockingEngine(()=>now);route=Route();route.Switches.AddRange(new[]{new RouteSwitch{Node="W1"},new RouteSwitch{Node="W2"}});Ready(e,route,w);e.RequestRelease(route.Id,"point:W1",0);e.ConfirmOperatorRelease(route.Id);e.Tick(w);Check(e.Active.Count==1&&e.Active.Single().ReleasedSwitches.Contains("W1")&&!e.Active.Single().ReleasedSwitches.Contains("W2")&&e.Locked("W2",true),"dispatcher-confirmed individual release leaves every unselected point and track lock intact");
        Incorporation();
    }
    static Tuple<RouteDefinition,RouteDefinition> Pair(){var shunt=Route(true);shunt.Entry="RS";shunt.Exit="RS2";shunt.Sections[0].From=20;shunt.Sections[0].To=80;shunt.Path=new List<DirectedRouteSection>{new DirectedRouteSection{Section=shunt.Sections[0]}};shunt.ViaSignals=new List<RouteViaSignal>();var main=Route();main.Path=new List<DirectedRouteSection>{new DirectedRouteSection{Section=main.Sections[0]}};main.ViaSignals=new List<RouteViaSignal>{new RouteViaSignal{Id="RS",Anchor="native",Distance=20,Downstream=new List<TrackSection>{shunt.Sections[0]}}};return Tuple.Create(shunt,main);}
    static void Incorporation(){double now=0;var pair=Pair();var w=new World();var e=new InterlockingEngine(()=>now);Ready(e,pair.Item1,w);e.Request(pair.Item2,w);Check(e.Active.Count==1&&e.Active.Single().Stage==RouteStage.Preparing&&e.Active.Single().IncorporatedFrom.SequenceEqual(new[]{pair.Item1.Id})&&!e.Active.Single().Permitted,"same-direction covered shunt route becomes one main-route resource set without a contradictory independent shunt authority");for(int i=0;i<8;i++)e.Tick(w);Check(e.Active.Single().Permitted&&e.Active.Single().PermitsVia("RS"),"incorporated main route authorizes its intermediate shunt signal after normal end-position and clear checks");
        pair=Pair();w=new World();e=new InterlockingEngine(()=>now);pair.Item1.Path[0].Reverse=true;Ready(e,pair.Item1,w);e.Request(pair.Item2,w);Check(e.Active.Count==2&&e.Active.Any(r=>r.Stage==RouteStage.WaitingProtection)&&e.Active.All(r=>!r.Permitted),"opposite-direction shunt path cannot be incorporated and is withdrawn through the protection sequence");
        pair=Pair();w=new World();e=new InterlockingEngine(()=>now);pair.Item1.Sections.Add(new TrackSection{Segment="flank",From=0,To=25});Ready(e,pair.Item1,w);e.Request(pair.Item2,w);Check(e.Active.Count==2&&e.Active.All(r=>!r.Permitted),"main route cannot silently discard an uncovered protection resource from the old shunt route");
        pair=Pair();w=new World();e=new InterlockingEngine(()=>now);Ready(e,pair.Item1,w);var bad=Route();bad.Code="bad";bad.Entry="B";bad.Exit="C";bad.Sections[0].Segment="bad";w.Unknown=false;bool failed=false;try{e.RequestChain(new[]{pair.Item2,bad},new BadWorld(w));}catch(InvalidOperationException){failed=true;}Check(failed&&e.Active.Count==1&&e.Active.Single().Route.Id==pair.Item1.Id&&e.Active.Single().Permitted,"failure of a later chain part restores an incorporated shunt route and its complete original locks");}
    sealed class BadWorld:IInterlockingWorld {readonly World w;public BadWorld(World world){w=world;}public bool PathValid(RouteDefinition r)=>true;public TrackOccupancy Occupancy(TrackSection s)=>s.Segment=="bad"?TrackOccupancy.Unknown:TrackOccupancy.Clear;public bool SwitchPosition(string id,out bool value)=>w.SwitchPosition(id,out value);public bool SetSwitch(string id,bool value)=>w.SetSwitch(id,value);}
}
